/**
 * SPEC 63 GG-14: stress for thin (dictionary-only, light, historical-linked) cards and stressed paradigm forms from SOURCES THAT PRINT IT — nothing is generated by a rule.
 * Sources: stress marks on the headwords of СУМ-11 / СУМ-20 (SeRow.a, allowed under GG-7: headword + stress), the acute accents of the r2u dictionaries (Грінченко, Желехівський, Уманець–Спілка …),
 * en.wiktionary via kaikki (CC BY-SA 4.0: headword and `forms` with stress). VESUM has no stress layer (its lines carry no accent), so it contributes none.
 * Every variant = [positions of the stressed vowels in the unstressed NFC form, source id, locator]. Conflicting positions are shown side by side, each with its source, never merged.
 * Sidecar lm/st/<bucket>.json (ST_BUCKETS buckets by lk(lemma)), shard { format: 1, src: string[], entries: { lk: [lemma as written, variants[], forms[]] } }. Pure.
 */
import { bucketOf } from './shard.ts'
import { lk } from './cv.ts'
import { fold } from './orthography.ts'
import { stripStress, stressPositions, renderStress } from './text.ts'

export const ST_BUCKETS = 512
export const ST_MAX_VARIANTS = 8, ST_MAX_FORMS = 80
export const stBucket = (k: string) => bucketOf(k, ST_BUCKETS)
export const stUrl = (b: number | string) => `./data/lm/st/${b}.json`

/** source id → name and the «за …» phrase */
export const ST_SOURCES: Record<string, { name: string; by: string; licence?: string }> = {
  sum11: { name: 'СУМ-11', by: 'за СУМ-11' },
  sum20: { name: 'СУМ-20', by: 'за СУМ-20' },
  hrinch: { name: 'Грінченко', by: 'за Грінченком' },
  zheleh: { name: 'Желехівський', by: 'за Желехівським' },
  umanets: { name: 'Уманець–Спілка', by: 'за Уманцем–Спілкою' },
  nikovsky: { name: 'Ніковський', by: 'за Ніковським' },
  krymsky: { name: 'Кримський–Єфремов', by: 'за Кримським–Єфремовим' },
  izyumov: { name: 'Ізюмов', by: 'за Ізюмовим' },
  doroshenko: { name: 'Дорошенко–Станиславський', by: 'за Дорошенком–Станиславським' },
  yakubski: { name: 'Якубські', by: 'за Якубськими' },
  ulif: { name: 'ukrainian-word-stress (дані ULIF)', by: 'за словником ULIF (ukrainian-word-stress)' },
  kaikki: { name: 'en.wiktionary (kaikki)', by: 'за en.wiktionary (kaikki, CC BY-SA 4.0)', licence: 'CC BY-SA 4.0' },
}
/** r2u dictionary id → source id (Грінченко's two editions share one source id; the locator names the edition) */
export const R2U_STRESS_SRC: Record<number, string> = { 9: 'umanets', 21: 'zheleh', 12: 'hrinch', 18: 'hrinch', 8: 'nikovsky', 1: 'krymsky', 2: 'izyumov', 5: 'doroshenko', 13: 'yakubski' }

export type StVariant = [positions: number[], src: number, loc: string]
export type StForm = [form: string, positions: number[], src: number]
export type StEntry = [lemma: string, variants: StVariant[], forms: StForm[]]
export interface StShard { format: 1; src: string[]; entries: Record<string, StEntry[]> }
export interface StCand { lemma: string; positions: number[]; src: string; loc: string }

const VOWELS = 'аеєиіїоуюя', OLD_VOWELS = VOWELS + 'ѣыэѵѧѫ'
const isV = (c: string, old = false) => (old ? OLD_VOWELS : VOWELS).includes(c.toLowerCase())

/** accented written form → { lemma (unstressed, as written), positions }; undefined unless it is ONE word with ≥ 1 acute, each on a vowel */
export function parseAccented(s: string, old = false): { word: string; positions: number[] } | undefined {
  const t = s.normalize('NFC').trim()
  if (!t || /\s/.test(t) || !/[́]/.test(t)) return undefined
  const { form, positions } = stressPositions(t)
  if (!/^\p{L}[\p{L}'’ʼ-]*$/u.test(form) || !positions.length) return undefined
  if (positions.some(p => p < 0 || !isV([...form][p] ?? '', old))) return undefined
  return { word: form, positions: [...new Set(positions)].sort((a, b) => a - b) }
}

/** the nth vowel (ordinal) of each position */
const ordinals = (w: string, ps: number[], old: boolean) => { const cs = [...w]; return ps.map(p => cs.slice(0, p + 1).filter(c => isV(c, old)).length - 1) }
const fromOrdinals = (w: string, os: number[]): number[] | undefined => {
  const idx = [...w].flatMap((c, i) => (isV(c) ? [i] : [])); const out = os.map(o => idx[o]); return out.every(x => x !== undefined) ? (out as number[]) : undefined
}

/**
 * An accented headword of a dictionary in the old orthography (`orth` = fold era) → the modern lemma, ONLY when the fold gives exactly one candidate and the vowels map one to one
 * (ѣ→і, ы→и …); otherwise undefined (counted by the caller as «не зіставлено»).
 */
export function modernCand(raw: string, src: string, loc: string, orth?: string): StCand | undefined {
  const p = parseAccented(raw, !!orth); if (!p) return undefined
  const low = p.word.toLowerCase().replace(/[’ʼ]/g, "'")
  if (!orth) return { lemma: low, positions: p.positions, src, loc }
  const cands = fold(low, orth)
  if (cands.length !== 1) return undefined
  const m = cands[0]!.form
  const os = ordinals(low, p.positions, true); const ps = fromOrdinals(m, os)
  if (!ps || [...m].filter(c => isV(c)).length !== [...low].filter(c => isV(c, true)).length) return undefined
  return { lemma: m, positions: ps, src, loc }
}

/** СУМ-11 / СУМ-20 headword with its stress mark (SeRow.a, or a head printed with the mark) */
export function sumCand(head: string, row: { d: string; a?: string; l?: string }): StCand | undefined {
  if (row.d !== 'sum11' && row.d !== 'sum20') return undefined
  const acc = row.a && /́/.test(row.a) ? row.a : /́/.test(head) ? head : undefined
  return acc ? modernCand(acc, row.d, row.l ?? '') : undefined
}

/** r2u row [dict, rowId, lookup, scope, head[], eq[], quote]: uk→ru / uk→de dictionaries print the Ukrainian headword with accents (the article's first word is the lemma, the later words are forms and are
 *  NOT taken); ru→uk dictionaries print the Ukrainian equivalents with accents (single-word equivalents are taken) */
export function r2uCands(row: [number, number, string, string, string[], string[], string], dir: string, orth: string, edition: string): StCand[] {
  const src = R2U_STRESS_SRC[row[0]]; if (!src) return []
  const loc = `r2u ${edition} #${row[1]}`, out: StCand[] = []
  if (dir === 'ru-uk') { for (const e of row[5]) { const c = modernCand(e, src, loc, orth); if (c) out.push(c) } }
  else if (dir !== 'orth') {
    const first = row[6].split(/[,.;/]|\s+и\s+/)[0]?.trim() ?? ''
    const c = modernCand(first, src, loc, orth); if (c) out.push(c)
  }
  return out
}

/** kaikki (en.wiktionary) Ukrainian entry → the lemma's stress and stressed forms. `forms[]` = { form, tags } as in the JSONL; the lemma stress is a form that strips to the headword */
export function kaikkiCands(e: { word?: string; lang_code?: string; forms?: { form?: string; tags?: string[] }[]; head_templates?: { expansion?: string }[] }, line?: number): { lemma: StCand[]; forms: { lemma: string; form: string; positions: number[]; src: string }[] } {
  const out = { lemma: [] as StCand[], forms: [] as { lemma: string; form: string; positions: number[]; src: string }[] }
  const w = e.word; if (!w || (e.lang_code && e.lang_code !== 'uk') || /\s/.test(w)) return out
  const loc = `en.wiktionary «${w}»${line !== undefined ? ` (kaikki, рядок ${line})` : ''}`
  const heads = [...(e.forms ?? []).filter(f => f.form && !(f.tags ?? []).some(t => /romani[sz]ation|transliteration/i.test(t))).map(f => f.form!), ...((e.head_templates ?? []).map(h => h.expansion?.split(/\s+/)[0] ?? ''))]
  const seen = new Set<string>()
  for (const f of (e.forms ?? [])) {
    if (!f.form || (f.tags ?? []).some(t => /romani[sz]ation|transliteration|table-tags|inflection-template|class/i.test(t))) continue
    const p = parseAccented(f.form); if (!p) continue
    const k = p.word + '|' + p.positions
    if (seen.has(k)) continue; seen.add(k)
    if (lk(p.word) === lk(w)) out.lemma.push({ lemma: w, positions: p.positions, src: 'kaikki', loc })
    else out.forms.push({ lemma: w, form: p.word, positions: p.positions, src: 'kaikki' })
  }
  if (!out.lemma.length) for (const h of heads) { const p = parseAccented(h); if (p && lk(p.word) === lk(w)) { out.lemma.push({ lemma: w, positions: p.positions, src: 'kaikki', loc }); break } }
  return out
}

/** streaming collector; crash-safe writing is the pipeline's (RS-1) */
export class StBuilder {
  private shards = new Map<number, { src: Map<string, number>; list: string[]; entries: Map<string, StEntry[]> }>()
  n = 0; nForms = 0
  private entry(lemma: string): { s: { src: Map<string, number>; list: string[] }; e: StEntry } | undefined {
    const k = lk(lemma); if (!k) return undefined
    const b = stBucket(k), s = this.shards.get(b) ?? (this.shards.set(b, { src: new Map(), list: [], entries: new Map() }), this.shards.get(b)!)
    const l = s.entries.get(k) ?? (s.entries.set(k, []), s.entries.get(k)!)
    let e = l.find(x => x[0] === lemma); if (!e) { if (l.length >= 3) return undefined; e = [lemma, [], []]; l.push(e) }
    return { s, e }
  }
  private sid(s: { src: Map<string, number>; list: string[] }, id: string): number { let i = s.src.get(id); if (i === undefined) { i = s.list.length; s.src.set(id, i); s.list.push(id) }; return i }
  add(c: StCand): void {
    const r = this.entry(c.lemma); if (!r) return
    const si = this.sid(r.s, c.src), v = r.e[1]
    if (v.length >= ST_MAX_VARIANTS || v.some(x => x[1] === si && x[2] === c.loc && x[0].join() === c.positions.join())) return
    v.push([c.positions, si, c.loc]); this.n++
  }
  addForm(f: { lemma: string; form: string; positions: number[]; src: string }): void {
    const r = this.entry(f.lemma); if (!r) return
    const si = this.sid(r.s, f.src), fs = r.e[2]
    if (fs.length >= ST_MAX_FORMS || fs.some(x => x[0] === f.form && x[2] === si && x[1].join() === f.positions.join())) return
    fs.push([f.form, f.positions, si]); this.nForms++
  }
  finish(): Map<number, StShard> {
    const out = new Map<number, StShard>()
    for (const [b, s] of this.shards) out.set(b, { format: 1, src: s.list, entries: Object.fromEntries([...s.entries].filter(([, l]) => l.some(e => e[1].length || e[2].length)).sort((a, c) => (a[0] < c[0] ? -1 : 1))) })
    return out
  }
}

export interface StLemma { lemma: string; variants: { positions: number[]; src: string; loc: string }[]; forms: { form: string; positions: number[]; src: string }[] }
export function stOfShard(shard: StShard | undefined, word: string): StLemma[] | undefined {
  const es = shard?.entries[lk(word)]; if (!es?.length) return undefined
  return es.map(([lemma, v, f]) => ({ lemma, variants: v.map(([positions, s, loc]) => ({ positions, src: shard!.src[s] ?? '?', loc })), forms: f.map(([form, positions, s]) => ({ form, positions, src: shard!.src[s] ?? '?' })) }))
}

export interface StGroup { positions: number[]; shown: string; sources: { src: string; name: string; loc: string }[] }
/** variants grouped by position set (same stress from several sources = one group with all of them); more than one group = a CONFLICT, shown side by side */
export function stGroups(word: string, vs: { positions: number[]; src: string; loc: string }[], extra: { positions: number[]; src: string; loc: string }[] = []): StGroup[] {
  const g = new Map<string, StGroup>()
  for (const v of [...extra, ...vs]) {
    const k = [...v.positions].sort((a, b) => a - b).join(',')
    const x = g.get(k) ?? (g.set(k, { positions: v.positions, shown: renderStress(word, v.positions), sources: [] }), g.get(k)!)
    if (!x.sources.some(s => s.src === v.src && s.loc === v.loc)) x.sources.push({ src: v.src, name: ST_SOURCES[v.src]?.name ?? v.src, loc: v.loc })
  }
  return [...g.values()]
}
/** «наголос за СУМ-11: ма́ти; за Грінченком: мати́» for ≥ 2 groups, '' otherwise */
export function conflictLine(groups: StGroup[]): string {
  if (groups.length < 2) return ''
  const part = (g: StGroup) => [...new Set(g.sources.map(s => ST_SOURCES[s.src]?.by ?? `за ${s.name}`))].join(', ') + ': ' + g.shown
  const [a, ...r] = groups.map(part)
  return `наголос ${a}; ${r.join('; ')}`
}
/** stress positions of a stripped form among the lemma's stressed forms (undefined: no source prints it) */
export const formStress = (forms: StLemma['forms'], form: string): { positions: number[]; src: string }[] =>
  forms.filter(f => stripStress(f.form).toLowerCase() === form.toLowerCase()).map(f => ({ positions: f.positions, src: f.src }))
